DECLARE k text; previous uuid; was_present boolean; v uuid; old_data jsonb; new_data jsonb;
BEGIN
 IF TG_OP<>'DELETE' THEN
  IF NEW.id IS NULL OR NEW.email IS NULL OR NEW.hashed_password IS NULL OR NEW.is_active IS NULL OR NEW.is_superuser IS NULL OR NEW.is_verified IS NULL THEN RETURN NEW; END IF;
  IF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'ORM fixed UUID mutation unsupported'; END IF;
  k:=NEW.id::text;
 ELSE k:=OLD.id::text; END IF;
 SELECT token,present INTO previous,was_present FROM "mtw_orm_v3_9290b53a9690"."_mtw_orm_state" WHERE key=k FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ORM key outside controlled fixed domain'; END IF;
 IF TG_OP<>'INSERT' AND (NOT was_present OR previous IS DISTINCT FROM OLD."_mtw_orm_version") THEN RAISE EXCEPTION 'ORM source chain mismatch'; END IF;
 v:=gen_random_uuid();
 old_data:=CASE WHEN TG_OP='INSERT' THEN NULL ELSE jsonb_build_object('id',OLD."id"::text,'email',OLD."email",'hashed_password',OLD."hashed_password",'is_active',OLD."is_active",'is_superuser',OLD."is_superuser",'is_verified',OLD."is_verified") END;
 new_data:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('id',NEW."id"::text,'email',NEW."email",'hashed_password',NEW."hashed_password",'is_active',NEW."is_active",'is_superuser',NEW."is_superuser",'is_verified',NEW."is_verified") END;
